Rule.Source:
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import sailpoint.api.Provisioner;
import sailpoint.object.Application;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningProject;
import sailpoint.object.ProvisioningResult;
import sailpoint.object.Rule;

String LDAP_APP = "LDAP ApacheDS";

Map result = new HashMap();
List details = new ArrayList();
result.put("details", details);
int ok = 0;
int failed = 0;

boolean disable = "Disable".equalsIgnoreCase(action);
if (!disable && !"Enable".equalsIgnoreCase(action)) {
    result.put("status", "FAILED");
    details.add("ERROR: action must be Disable or Enable, not " + action);
    return result;
}
Identity identity = context.getObjectByName(Identity.class, identityName);
if (identity == null) {
    result.put("status", "FAILED");
    details.add("ERROR: identity " + identityName + " not found");
    return result;
}
boolean hrTerminated = "Terminated".equals(identity.getAttribute("status"));

// Collect the work first: the LDAP rule commits, which must not happen mid-iteration
List ldapLinks = new ArrayList();
ProvisioningPlan plan = new ProvisioningPlan();
plan.setIdentity(identity);
List planned = new ArrayList();

List links = identity.getLinks();
if (links != null) {
    for (Object o : links) {
        Link link = (Link) o;
        Application app = link.getApplication();
        String label = app.getName() + " / " + link.getNativeIdentity();

        if (app.isAuthoritative()) {
            details.add("SKIPPED " + label + ": authoritative source, not changed");
            continue;
        }
        if (disable == link.isDisabled()) {
            details.add("SKIPPED " + label + ": already " + (disable ? "disabled" : "enabled"));
            continue;
        }
        if (!disable && hrTerminated) {
            details.add("SKIPPED " + label + ": HR status is Terminated, account stays disabled");
            continue;
        }
        if (LDAP_APP.equals(app.getName())) {
            ldapLinks.add(link.getNativeIdentity());
        } else if (app.supportsFeature(Application.Feature.ENABLE)) {
            AccountRequest ar = new AccountRequest();
            ar.setApplication(app.getName());
            ar.setNativeIdentity(link.getNativeIdentity());
            ar.setInstance(link.getInstance());
            ar.setOperation(disable ? AccountRequest.Operation.Disable : AccountRequest.Operation.Enable);
            plan.add(ar);
            planned.add(label);
        } else {
            failed++;
            details.add("MANUAL " + label + ": connector cannot " + action.toLowerCase()
                        + " accounts, " + action.toLowerCase() + " it on the target system");
        }
    }
}

// LDAP ApacheDS: same path as the HR leaver / rehire process
if (!ldapLinks.isEmpty()) {
    Rule setStatus = context.getObjectByName(Rule.class, "LDAP ApacheDS - Set Account Status");
    if (setStatus == null) {
        failed++;
        details.add("FAILED " + LDAP_APP + ": rule 'LDAP ApacheDS - Set Account Status' not found");
    } else {
        Map args = new HashMap();
        args.put("identityName", identityName);
        args.put("action", disable ? "Disable" : "Enable");
        try {
            String r = String.valueOf(context.runRule(setStatus, args));
            if (r.startsWith("DISABLED") || r.startsWith("ENABLED")) ok++; else failed++;
            details.add((r.startsWith("ERROR") ? "FAILED " : "") + LDAP_APP + ": " + r);
        } catch (Exception e) {
            failed++;
            details.add("FAILED " + LDAP_APP + ": " + e.getMessage());
            log.error("Emergency Identity: LDAP " + action + " failed for " + identityName, e);
        }
    }
}

// Other applications: IIQ provisioner, no approvals
if (!planned.isEmpty()) {
    try {
        plan.setSource("EmergencyIdentityStatus");
        Identity requester = (launcher == null) ? null : context.getObjectByName(Identity.class, launcher);
        if (requester != null) {
            List requesters = new ArrayList();
            requesters.add(requester);
            plan.setRequesters(requesters);
        }
        Provisioner p = new Provisioner(context);
        p.execute(plan);

        ProvisioningProject project = p.getProject();
        List plans = (project == null) ? null : project.getPlans();
        if (plans != null) {
            for (Object po : plans) {
                ProvisioningPlan pp = (ProvisioningPlan) po;
                if (pp.getAccountRequests() == null) continue;
                for (Object ao : pp.getAccountRequests()) {
                    AccountRequest ar = (AccountRequest) ao;
                    ProvisioningResult r = ar.getResult();
                    if (r == null) r = pp.getResult();
                    String label = ar.getApplication() + " / " + ar.getNativeIdentity();
                    if (r != null && r.isFailed()) {
                        failed++;
                        details.add("FAILED " + label + ": " + r.getErrors());
                    } else {
                        ok++;
                        details.add((disable ? "DISABLED " : "ENABLED ") + label
                                    + (r == null ? "" : " (" + r.getStatus() + ")"));
                    }
                }
            }
        }
        if (project != null && project.getUnmanagedPlan() != null) {
            failed++;
            details.add("MANUAL: some requests could not be sent to a connector, see the manual work items");
        }
    } catch (Exception e) {
        failed++;
        details.add("FAILED provisioning " + planned + ": " + e.getMessage());
        log.error("Emergency Identity: provisioning failed for " + identityName, e);
    }
}

if (ok == 0 && failed == 0) result.put("status", "NOTHING_TO_DO");
else if (failed == 0)       result.put("status", "SUCCESS");
else if (ok == 0)           result.put("status", "FAILED");
else                        result.put("status", "PARTIAL");
return result;
